alario> (SELECT avg{salario) FROM investigadores);','SELECT nombre, salario FROM investigadores WHERE salario > (SELECT avg(salario) FROM investigadores GROUP BY dep_ld};','b',2016,'3','s',16,3,95,NULL,3,NULL,4,'distractor por similitud.',NULL,'distractor: **subconsulta simple**','distractor por similitud.'),(1307,'¿Cuál de las siguientes consultas selecciona el \"tercer salario mínimo\" de los investigadores del departamento de Inteligencia Artificial (dep_nombre=\'IN_AR\'}?','SELECT DISTlNCT salario, dep_id FROM Investigadores el WHERE dep_nombre=\'IN_AR\' AND 3 = (SELECT COUNT(DISTINCT salario) FROM investigadores e2 WHERE e2.salario <= e1.salario);','SELECT DISTINCT e1.salario, e1.dep_id FROM Investigadores e1, departamentos d1 WHERE e1.dep_id=d1.dep_id AND d1.dep_nombre=\'IN_AR\' AND 3 = (SELECT DISTlNC salario FROM investigadores e2 WHERE e2.salario <= e1.salario);','SELECT DISTINCT e1.salario, e1.dep_id FROM Investigadores WHERE dep_nombre =\'IN_AR\' AND 3 = (SELECT COUNT(DISTINCT salario) FROM investigadores e2 WHERE e2.salario <= e1.salario);','SELECT DISTINCT e1.salario, e1.dep_id FROM investigadores e1, departamentos d1 WHERE e1.dep_id=d1.dep_id AND d1.dep_nombre=\'IN_AR\' AND 3 = (SELECT COUNT(DISTINCT salario) FROM investigadores e2, departamentos d2 WHERE e2.dep_id=d2.dep_id AND d2.dep_nombre=\'IN_AR\'AND e2.salario <= e1.salario);','b',2016,'3','s',17,3,95,NULL,4,NULL,3,'similitud sintáctica',NULL,'similitud sintáctica','similitud sintáctica'),(1308,'Marque la consulta para sacar la fecha actual del sistema en MySql en el siguiente formato: Marzo 5, 2017','SELECT DATE_FORMAT(CURDATE(),\'%M %e, %Y\')','SELECT DATE_FORMAT(CURDATE(),\'%m %0, %y\')','SELECT DATE_FORMAT(DATE(),\'%m %d, %A\')','SELECT DATE_FORMAT(DATE(),\'%M %d, %a\')','a',2016,'3','s',18,3,95,NULL,2,NULL,1,NULL,'formato incorrecto','formato incorrecto','distractor semántico'),(1309,'Seleccione la consulta que extrae los investigadores que se contrataron en el mes de octubre de cualquier añ